"use strict";
const $=id=>document.getElementById(id),t=OrionI18n.t;
const journeys=[[6,7,1],[5,9,1],[1,11,8],[10,1,3],[13,4,1],[1,2,12]];
let variant=OrionProgress.variant('primes'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,rows=1,tested=new Set(),solved=false,hintDepth=0,hintOpen=false,state='ready',saveFailed=false;
function challenge(v=variant,s=stage){return journeys[v][s];}
function factors(n){return Array.from({length:n},(_,i)=>i+1).filter(d=>n%d===0);}
function kind(n=challenge()){return n===1?'neither':factors(n).length===2?'prime':'composite';}
function setRows(n){if(solved||!Number.isInteger(n)||n<2||n>=challenge())return;rows=n;tested.add(n);state='ready';render();}
function evidence(){return kind()==='neither'||kind()==='prime'&&tested.size===challenge()-2||kind()==='composite'&&[...tested].some(d=>challenge()%d===0);}
function resetTrial(){rows=1;tested=new Set();solved=false;hintDepth=0;hintOpen=false;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('primes')){variant=v;stage=0;resetTrial();}
function check(answer){if(solved||!['prime','composite','neither'].includes(answer))return;if(answer!==kind())state='wrong';else if(!evidence())state='evidence';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('indivisible');}render();if(solved&&stage<2)$('next').focus();}
function drawing(){const n=challenge(),cols=Math.ceil(n/rows),size=Math.min(24,200/rows,300/cols),left=(350-cols*size)/2,top=(240-rows*size)/2;let cells='';for(let i=0;i<rows*cols;i++){const x=left+(i%cols)*size,y=top+Math.floor(i/cols)*size;cells+=i<n?`<path d="M${x+size/2} ${y+2}l${size/2-2} ${size/2-2}l${2-size/2} ${size/2-2}l${2-size/2} ${2-size/2}Z" fill="#a5edcd" stroke="#456b65"/>`:`<rect x="${x+2}" y="${y+2}" width="${size-4}" height="${size-4}" fill="none" stroke="#adbbba" stroke-dasharray="2 2"/>`;}
return `<svg viewBox="0 0 350 240" role="img" aria-label="${t('Gems: '+n+'; rows: '+rows+'; empty spaces: '+(rows*cols-n),n+' 顆寶石排成 '+rows+' 行，'+(rows*cols-n)+' 個空位')}">${cells}</svg>`;}
function hints(){const n=challenge(),f=factors(n);return[t('Try the row buttons. A filled rectangle has no empty spaces. Each side must be longer than one.','試按行數按鈕。填滿的長方形沒有空位，而且兩邊都要多於一。'),t('A prime has exactly two positive factors: 1 and itself. A composite has more. The number 1 is neither.','質數只有兩個正因數：1 和本身。合成數有更多。1 兩者都不是。'),t(n+' has these positive factors: '+f.join(', ')+'. Use them to choose its shelf.',n+' 的正因數是 '+f.join('、')+'。根據它們選擇書架。')];}
function render(){const n=challenge(),complete=solved&&stage===2,p=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Prime Gem Archive · Orion','質數寶石檔案館 · Orion');$('stageTitle').textContent=t(`Tray ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 盤 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Archive seals · ${p} / 3`,`檔案封印 · ${p} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<p?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);$('diagram').innerHTML=drawing();
$('rowChoices').innerHTML=Array.from({length:Math.max(0,n-2)},(_,i)=>i+2).map(d=>`<button data-rows="${d}" aria-pressed="${rows===d}" ${solved?'disabled':''} aria-label="${t('Try '+d+' rows','試排 '+d+' 行')}">${d}${tested.has(d)?' ✓':''}</button>`).join('');
$('rowLabel').textContent=n<=2?t('No additional row counts to test.','沒有其他需要測試的行數。'):t('Tap a row count to test it:','點選行數進行測試：');$('goal').textContent=t('Choose a shelf for this tray. Gem count: '+n+'.','把這盤 '+n+' 顆寶石放到正確書架。');const cols=Math.ceil(n/rows),empty=rows*cols-n;$('reading').textContent=t('Rows: '+rows+' · Columns: '+cols+' · Empty spaces: '+empty,rows+' 行 × '+cols+' 列 · '+empty+' 個空位');$('reference').textContent=t('Tested rows: '+([...tested].sort((a,b)=>a-b).join(', ')||'none'),'已測試行數：'+([...tested].sort((a,b)=>a-b).join('、')||'未有'));
const messages={ready:['Explore the rows, then choose a shelf.','探索行數，然後選擇書架。'],wrong:['That shelf does not match. Look for a filled rectangle, or try the clue rune.','這個書架不合適。找找能否排成沒有空位的長方形，或點選提示符文。'],evidence:['Gather evidence first: find a filled rectangle for composite, or test every offered row count for prime.','先蒐集證據：合成數要找到填滿的長方形；質數要試完所有提供的行數。'],success:['Filed correctly! Another archive seal opens.','分類正確！又一道檔案封印打開。']};$('feedback').textContent=t(...messages[state]);$('classify').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintOpen));$('hints').hidden=!hintOpen;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('')+`<li class="close-clues"><button data-close>${t('Close clues','關閉提示')}</button></li>`;
$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('indivisible')?t('Primeheart Sigil saved in your collection.','質心符印已存入收藏。'):'';}
$('rowChoices').onclick=e=>{const b=e.target.closest('button[data-rows]');if(b)setRows(Number(b.dataset.rows));};
for(const k of ['prime','composite','neither'])$(k).onclick=()=>check(k);
$('hints').onclick=e=>{if(e.target.closest('button[data-close]')){hintOpen=false;render();$('hint').focus();}};window.addEventListener('keydown',e=>{if(e.key==='Escape'&&hintOpen){hintOpen=false;render();$('hint').focus();}});$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);hintOpen=true;render();};
$('replay').onclick=()=>{const v=OrionProgress.nextVariant('primes',variant);observedVariant=OrionProgress.variant('primes');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('indivisible');render();};function syncProgress(){const v=OrionProgress.variant('primes'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('indivisible')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
